const standardDeviations = [1, 2, 4];
const repeatCounts = [1, 3, 5];

export function followupPrediction(x, sigma, repeats) {
  if (
    !Number.isFinite(x) ||
    x < 0 ||
    x > 4 ||
    !Number.isInteger(x * 4) ||
    !standardDeviations.includes(sigma) ||
    !repeatCounts.includes(repeats)
  ) {
    throw new RangeError("Choose a listed concentration, standard deviation and repeat count.");
  }
  const quadratic = 6 + 4 * x - x * x;
  const quartic = quadratic - x * (x - 1) * (x - 3) * (x - 4);
  return {
    x,
    sigma,
    repeats,
    quadratic,
    quartic,
    gap: Math.abs(quadratic - quartic),
    errorProbability:
      probabilities[x * 4][standardDeviations.indexOf(sigma)][repeatCounts.indexOf(repeats)],
  };
}

export function formatErrorProbability(probability) {
  if (!Number.isFinite(probability) || probability < 0 || probability > 0.5) {
    throw new RangeError("Expected an error probability between zero and one half.");
  }
  if (probability > 0 && probability < 0.0001) return "<0.01%";
  return `${(probability * 100).toFixed(2)}%`;
}

export function mountFollowupDesign(doc) {
  const panel = doc.getElementById("followup-design");
  if (!panel) return;
  const el = (id) => doc.getElementById(`followup-${id}`);
  const concentration = el("x");
  const sigma = el("sigma");
  const repeats = el("repeats");
  const controls = el("controls");
  const chinese = doc.documentElement?.lang?.startsWith("zh") === true;
  const update = () => {
    const prediction = followupPrediction(
      Number(concentration.value),
      Number(sigma.value),
      Number(repeats.value),
    );
    const xText = prediction.x.toFixed(2);
    el("x-value").textContent = `${xText}%`;
    concentration.setAttribute(
      "aria-valuetext",
      chinese ? `氯化铵浓度 ${xText}%` : `${xText} percent ammonium chloride`,
    );
    el("quadratic").textContent = `${prediction.quadratic.toFixed(2)}%`;
    el("quartic").textContent = `${prediction.quartic.toFixed(2)}%`;
    el("gap").textContent = prediction.gap.toFixed(2);
    el("error").textContent = formatErrorProbability(prediction.errorProbability);
    el("reading").textContent = chinese
      ? prediction.gap === 0
        ? `在 ${xText}% 处，两个假设都预测 ${prediction.quadratic.toFixed(2)}% 得率。在这个模型下，重复测量同一浓度无法区分它们；理论错误概率始终为 50%。`
        : `在 ${xText}% 处，两项预测相差 ${prediction.gap.toFixed(2)} 个百分点。已知标准差为 ${prediction.sigma}、独立测量 ${prediction.repeats} 次时，理论错误概率为 ${formatErrorProbability(prediction.errorProbability)}。`
      : prediction.gap === 0
        ? `At ${xText}%, both hypotheses predict ${prediction.quadratic.toFixed(2)}% yield. Repeating this concentration cannot distinguish them under this model; the theoretical error stays at 50%.`
        : `At ${xText}%, the predictions differ by ${prediction.gap.toFixed(2)} percentage points. With SD ${prediction.sigma} and ${prediction.repeats} independent ${prediction.repeats === 1 ? "measurement" : "measurements"}, the theoretical error is ${formatErrorProbability(prediction.errorProbability)}.`;
    const plotX = 44 + prediction.x * 122;
    const plotY = (yieldValue) => 240 - (yieldValue - 6) * 43;
    const qY = plotY(prediction.quadratic);
    const fY = plotY(prediction.quartic);
    const guide = el("guide");
    guide.setAttribute("x1", plotX);
    guide.setAttribute("x2", plotX);
    guide.setAttribute("y1", Math.min(qY, fY));
    guide.setAttribute("y2", Math.max(qY, fY));
    for (const [id, value] of [
      ["q-point", qY],
      ["f-point", fY],
    ]) {
      el(id).setAttribute("cx", plotX);
      el(id).setAttribute("cy", value);
    }
    el("plot-description").textContent = chinese
      ? `二次与四次响应在原来的四个浓度上相同。在当前选择的 ${xText}% 处，它们分别预测 ${prediction.quadratic.toFixed(2)}% 和 ${prediction.quartic.toFixed(2)}% 精油得率。`
      : `The quadratic and quartic agree at the four original concentrations. At the selected ${xText}%, they predict ${prediction.quadratic.toFixed(2)}% and ${prediction.quartic.toFixed(2)}% oil yield, respectively.`;
  };
  for (const control of [concentration, sigma, repeats]) {
    control.addEventListener("input", update);
    control.addEventListener("change", update);
  }
  update();
  controls.disabled = false;
  el("interaction-note").textContent = chinese
    ? "先试 1%，再试 2%。使用方向键可以每次调整 0.25%。"
    : "Try 1%, then 2%. Use the arrow keys to move by 0.25%.";
}

if (typeof document !== "undefined") mountFollowupDesign(document);
